(() => {
'use strict';
const D=Demo,E=v=>App.e(v??''),I=(n,s=18)=>App.icon(n,s),S=()=>D.state,U=id=>S().users.find(u=>u.id===id),Dev=id=>S().devices.find(d=>d.id===id);
const sum=rows=>rows.reduce((a,r)=>a+r.amountCents,0),yen=n=>'¥ '+App.money(n),month=v=>new Date(Date.parse(v)+28800000).toISOString().slice(0,7),dateValue=v=>new Date(Date.parse(v)+28800000).toISOString().slice(0,16),toIso=v=>v+':00+08:00';
const q=()=>App.ui.adminSearch?.[App.ui.page]||'',selectedMonth=()=>App.ui.reportMonth||month(S().now);
const button=(action,label,icon='',id='',kind='')=>'<button type="button" class="btn '+kind+'" data-admin="'+action+'" data-id="'+E(id)+'">'+(icon?I(icon,16):'')+label+'</button>';
const link=(action,label,id)=>'<button type="button" class="text-link" data-admin="'+action+'" data-id="'+E(id)+'">'+label+'</button>';
const head=(k,title,desc,actions='')=>'<div class="page-head"><div><div class="eyebrow">'+k+'</div><h1>'+title+'</h1><p>'+desc+'</p></div><div class="row">'+actions+'</div></div>';
const badgeLease=d=>{const l=D.lease(d.id);return App.badge(l.label,l.key==='expired'?'danger':l.key==='near'?'warning':l.key==='stock'?'muted':'success')};
const status=d=>App.badge(!d.online?'离线':d.fault?'故障':d.run?'运行中':'已停止',!d.online?'muted':d.fault?'danger':d.run?'success':'info');
const customer=(id,fallback)=>U(id)?.name||fallback||'资料未登记';
function table(headers,rows,empty='暂无符合条件的记录'){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+headers.length+'"><div class="empty">'+I('inbox',30)+'<strong>'+empty+'</strong><span>调整筛选条件或新增业务记录。</span></div></td></tr>')+'</tbody></table></div>';}
const cell=v=>'<td>'+v+'</td>',row=values=>'<tr>'+values.map(cell).join('')+'</tr>';
const field=(label,html,hint='')=>'<label class="field"><span>'+label+'</span>'+html+(hint?'<small>'+hint+'</small>':'')+'</label>';
const input=(name,value='',type='text',extra='')=>'<input name="'+name+'" type="'+type+'" value="'+E(value)+'" '+extra+'>';
const formEnd=label=>'<div class="form-actions"><button type="button" class="btn" data-close>取消</button><button type="submit" class="btn primary">'+label+'</button></div></form>';
function amount(v){if(!/^\d+(\.\d{1,2})?$/.test(String(v)))throw Error('金额必须为正数，且最多保留两位小数');const [a,b='']=String(v).split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n<=0)throw Error('请输入有效金额');return n;}
function csv(name,headers,rows){const protect=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};App.download(name,'\ufeff'+[headers,...rows].map(r=>r.map(protect).join(',')).join('\r\n'),'text/csv;charset=utf-8');App.toast('统计文件已生成，可保存至本地或 U 盘');}
function monthlyReceipts(){return S().receipts.filter(r=>month(r.paidAt)===selectedMonth())}
function stat(label,value,foot,ico){return '<div class="metric"><div class="metric-top"><span>'+label+'</span>'+I(ico,20)+'</div><div class="metric-number">'+value+'</div><div class="metric-foot">'+foot+'</div></div>'}
function overview(){
 const s=S(),nowMonth=month(s.now),receipts=s.receipts.filter(r=>month(r.paidAt)===nowMonth),active=s.devices.filter(d=>['active','near'].includes(D.lease(d.id).key)),due=s.devices.filter(d=>['near','expired'].includes(D.lease(d.id).key)).sort((a,b)=>D.lease(a.id).days-D.lease(b.id).days);
 const months=Array.from({length:6},(_,i)=>{const d=new Date(nowMonth+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-(5-i));const key=month(d.toISOString());return{key,total:sum(s.receipts.filter(r=>month(r.paidAt)===key))}}),max=Math.max(...months.map(x=>x.total),1);
 return head('OPERATIONS OVERVIEW','运营工作概览','管理设备、租赁合同与收入，掌握每一台变频器的服务状态。',button('inventory','扫码入库','scan-line','','primary'))+
 '<div class="welcome"><div><span class="eyebrow">设备租赁 · 全流程协同</span><h2>从设备入库，到每一次安心运行</h2><p>本地登记客户与授权，云端承载监控和运营。当前为完整业务演示，所有设备与收款均为样例数据。</p></div><div class="welcome-graphic">'+I('radio-tower',42)+'</div></div>'+
 '<div class="metric-grid">'+stat('在册设备',s.devices.length+'<small>台</small>',s.devices.filter(d=>d.online).length+' 台在线 · '+s.devices.filter(d=>!d.online).length+' 台离线','cpu')+stat('有效租赁',active.length+'<small>台</small>',s.devices.filter(d=>D.lease(d.id).key==='stock').length+' 台库存待出租','file-check-2')+stat('本月实际收款',yen(sum(receipts)),nowMonth+' · '+receipts.length+' 笔登记收款','wallet')+stat('到期需处理',due.length+'<small>台</small>',due.filter(d=>D.lease(d.id).key==='expired').length+' 台到期 · '+due.filter(d=>D.lease(d.id).key==='near').length+' 台 7 天内到期','calendar-clock')+'</div>'+
 '<div class="split"><div class="stack"><section class="panel"><div class="panel-head"><h2>租赁到期待办</h2>'+link('goto-reminders','全部提醒 →','')+'</div>'+table(['设备 / 客户','到期时间','租约状态','办理'],due.map(d=>{const c=D.contract(d.id);return row(['<strong>'+E(d.name)+'</strong><small>'+E(customer(c.ownerId))+'</small>',E(App.time(c.end)),badgeLease(d),button('renew','续租登记','',d.id,'small')])}))+'</section><section class="panel"><div class="panel-head"><h2>近 6 个月实际收款</h2>'+link('goto-reports','查看统计表 →','')+'</div><div class="panel-body"><div class="chart-bars">'+months.map(m=>'<div class="chart-bar" style="height:'+Math.max(2,m.total/max*110)+'px"><span>'+App.money(m.total)+'</span><small>'+m.key.slice(5)+' 月</small></div>').join('')+'</div><p class="muted" style="font-size:11px;margin-top:12px">按收款登记日期统计，不计未收租金。</p></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>快捷办理</h2></div><div class="panel-body"><div class="quick-grid" style="grid-template-columns:repeat(2,1fr)">'+[['inventory','扫码入库','scan-line'],['contract','合同登记','file-plus-2'],['new-user','登记客户','user-round-plus'],['goto-permissions','授予权限','shield-check']].map(([a,l,i])=>'<button type="button" class="quick-btn" data-admin="'+a+'">'+I(i,23)+l+'</button>').join('')+'</div></div></section><section class="panel"><div class="panel-head"><h2>主数据同步</h2>'+App.badge(s.sync.online?'连接正常':'主服务离线',s.sync.online?'success':'warning')+'</div><div class="panel-body"><dl class="info-list"><dt>本地主档</dt><dd>v'+s.sync.localVersion+'</dd><dt>云端副本</dt><dd>v'+s.sync.cloudVersion+'</dd><dt>待同步版本</dt><dd>'+s.sync.pending+'</dd></dl>'+button('goto-backup','备份与同步管理','database-backup','','small')+'</div></section></div></div>';
}
function deviceRows(){
 const term=q().toLowerCase(),filter=App.ui.deviceFilter||'all';
 return S().devices.filter(d=>[d.id,d.name,d.module,d.model,d.region,customer(D.contract(d.id)?.ownerId)].join(' ').toLowerCase().includes(term)&&(filter==='all'||filter==='stock'&&!D.contract(d.id)||filter==='offline'&&!d.online||filter==='fault'&&d.fault||filter==='near'&&['near','expired'].includes(D.lease(d.id).key))).map(d=>{const c=D.contract(d.id);return row(['<strong>'+E(d.name)+'</strong><small>'+E(d.id)+' · '+E(d.model)+'</small>',E(d.module),E(d.region)+'<small>'+E(d.place)+'</small>',status(d),c?E(customer(c.ownerId)):'<span class="muted">待签约</span>',badgeLease(d),'<div class="row">'+link('device','详情',d.id)+(c?link('renew','续租',d.id):link('contract','登记合同',d.id))+link('permissions-device','授权',d.id)+'</div>'])});
}
function devices(){return head('DEVICE INVENTORY','设备管理','二维码一物一码，手机与电脑均可登记入库。',button('inventory','扫码入库','scan-line','','primary'))+'<section class="panel"><div class="toolbar"><div class="tabs">'+[['all','全部设备'],['stock','库存待租'],['near','到期关注'],['offline','离线'],['fault','故障']].map(([k,l])=>'<button type="button" data-admin="device-filter" data-id="'+k+'" class="'+((App.ui.deviceFilter||'all')===k?'active':'')+'">'+l+'</button>').join('')+'</div><input id="admin-search" aria-label="搜索设备" placeholder="名称 / 模块 ID / 客户" value="'+E(q())+'"></div><div id="admin-results">'+table(['设备','4G 模块 ID','区域 / 位置','运行状态','第一所有人','租约','操作'],deviceRows())+'</div><div class="table-foot">共 '+S().devices.length+' 台 · 所有运行状态均为模拟数据</div></section>';}
function deviceDetail(id){const d=Dev(id),c=D.contract(id);if(!d)return;App.ui.deviceId=id;App.modal('设备资料 · '+d.name,'<div class="row" style="margin-bottom:18px">'+status(d)+badgeLease(d)+'</div><dl class="info-list"><dt>设备 ID</dt><dd>'+E(d.id)+'</dd><dt>厂商 / 型号</dt><dd>'+E(d.vendor)+' / '+E(d.model)+'</dd><dt>4G 模块 ID</dt><dd>'+E(d.module)+'</dd><dt>安装位置</dt><dd>'+E(d.region)+' · '+E(d.place)+'</dd><dt>第一所有人</dt><dd>'+E(c?customer(c.ownerId):'待登记合同')+'</dd><dt>租期结束</dt><dd>'+E(c?App.time(c.end):'未登记')+'</dd><dt>最后上报</dt><dd>'+E(App.time(d.lastSeen))+'</dd></dl><div class="mini-code">'+E(D.qr(d))+'</div><div class="banner" style="margin-top:15px">用户扫描此码只获得查看权限，合同归属及操作权限由管理员另行登记。</div><div class="row">'+button('monitor-device','打开设备监控','activity',id,'primary')+button(c?'renew':'contract',c?'续租登记':'合同登记','file-text',id)+button('permissions-device','管理授权','shield-check',id)+'</div>',el=>el.onclick=onClick)}


function nextMonth(v){const d=new Date(Date.parse(v)+28800000),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(Math.min(day,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));return d.toISOString().slice(0,16);}
function leases(){const term=q().toLowerCase(),rows=S().contracts.filter(c=>[c.number,customer(c.ownerId),U(c.ownerId)?.phone,Dev(c.deviceId)?.name].join(' ').toLowerCase().includes(term)).map(c=>{const d=Dev(c.deviceId),u=U(c.ownerId);return row(['<strong>'+E(c.number)+'</strong><small>'+E(d?.name)+'</small>',E(u?.name)+'<small>'+E(u?.phone)+'</small>',E(App.time(c.start))+'<small>至 '+E(App.time(c.end))+'</small>',yen(c.monthlyCents),badgeLease(d),yen(sum(S().receipts.filter(r=>r.contractId===c.id))),'<div class="row">'+link('lease','详情',c.deviceId)+link('renew','续租收款',c.deviceId)+'</div>'])});
 return head('LEASE MANAGEMENT','租赁合同','以签约并登记付款的客户为第一所有人，合同登记不会自动授予控制权限。',button('contract','登记合同与收款','file-plus-2','','primary'))+'<section class="panel"><div class="toolbar"><span class="muted">已登记 '+S().contracts.length+' 份合同</span><input id="admin-search" aria-label="搜索合同" value="'+E(q())+'" placeholder="合同号 / 客户 / 手机号"></div><div id="admin-results">'+table(['合同 / 设备','第一所有人','租赁期间','月租金','状态','累计实收','操作'],rows)+'</div></section>';
}
function openContract(deviceId=''){
 const stock=S().devices.filter(d=>!D.contract(d.id)),users=S().users.filter(u=>u.role!=='admin');
 if(!stock.length){App.toast('暂无待签约设备，请先扫码入库');return}
 if(!users.length){openUser();return}
 App.modal('登记合同与首次收款','<form id="contract-form"><div class="banner">确认签约客户与付款记录后，建立第一所有人关系。启停、调频等权限需另行授权。</div><div class="fields">'+
 field('待出租设备','<select name="deviceId">'+stock.map(d=>'<option value="'+E(d.id)+'" '+(d.id===deviceId?'selected':'')+'>'+E(d.name)+' · '+E(d.id)+'</option>').join('')+'</select>')+
 field('签约客户 · 微信绑定手机号','<select name="phone">'+users.map(u=>'<option value="'+E(u.phone)+'">'+E(u.name)+' · '+E(u.phone)+'</option>').join('')+'</select>')+
 field('合同编号',input('number','HT-'+month(S().now).replace('-','')+'-'+String(S().contracts.length+1).padStart(4,'0'),'text','required maxlength="60"'))+
 field('每月租金（元）',input('monthly','1500.00','number','required min="0.01" step="0.01"'))+
 field('租赁开始',input('start',dateValue(S().now),'datetime-local','required'))+
 field('租赁结束',input('end',nextMonth(S().now),'datetime-local','required'))+
 field('本次实际收款（元）',input('amount','1500.00','number','required min="0.01" step="0.01"'))+
 field('实际收款时间',input('paidAt',dateValue(S().now),'datetime-local','required'))+
 field('收款凭证 / 流水号',input('reference','DEMO-'+Date.now(),'text','required maxlength="120"'),'凭证号唯一，重复收款会被拦截。')+'</div><label class="check-row"><input name="verified" type="checkbox" required><span>已核对签约客户、合同时间和实际收款记录（演示登记，不发起支付）。</span></label>'+formEnd('确认登记合同与收款'),el=>{
 const f=el.querySelector('form');f.onsubmit=ev=>{ev.preventDefault();try{const v=Object.fromEntries(new FormData(f));D.registerContract({deviceId:v.deviceId,phone:v.phone,number:v.number,start:toIso(v.start),end:toIso(v.end),monthlyCents:amount(v.monthly),amountCents:amount(v.amount),paidAt:toIso(v.paidAt),reference:v.reference},'admin');App.ui.deviceId=v.deviceId;App.closeModal();App.toast('合同与收款已登记，操作权限仍需单独授予')}catch(err){App.error(f,err)}};
 });
}
function openRenew(id){const c=D.contract(id),d=Dev(id);if(!c||!d)return;const base=Date.parse(c.end)>Date.parse(S().now)?c.end:S().now;App.modal('续租登记 · '+d.name,'<form id="renew-form"><div class="banner">本次续租保持第一所有人不变。到期设备续租后解除租期限制，不会自动启动。</div><dl class="info-list"><dt>合同编号</dt><dd>'+E(c.number)+'</dd><dt>签约客户</dt><dd>'+E(customer(c.ownerId))+'</dd><dt>原到期时间</dt><dd>'+E(App.time(c.end))+'</dd></dl><div class="fields">'+field('续租后到期时间',input('end',nextMonth(base),'datetime-local','required'))+field('本次实收（元）',input('amount',(c.monthlyCents/100).toFixed(2),'number','required min="0.01" step="0.01"'))+field('收款时间',input('paidAt',dateValue(S().now),'datetime-local','required'))+field('收款凭证 / 流水号',input('reference','RENEW-'+Date.now(),'text','required maxlength="120"'))+'</div><label class="check-row"><input name="verified" type="checkbox" required><span>已核对续租时间与实际收款记录。</span></label>'+formEnd('确认续租与收款'),el=>{const f=el.querySelector('form');f.onsubmit=ev=>{ev.preventDefault();try{const v=Object.fromEntries(new FormData(f));D.renew({deviceId:id,end:toIso(v.end),amountCents:amount(v.amount),paidAt:toIso(v.paidAt),reference:v.reference},'admin');App.closeModal();App.toast('续租已登记，设备保持当前运行状态')}catch(err){App.error(f,err)}}})}
function users(){const rows=S().users.filter(u=>u.role!=='admin'&&[u.name,u.phone].join(' ').toLowerCase().includes(q().toLowerCase())).map(u=>{const owned=S().contracts.filter(c=>c.ownerId===u.id),added=S().memberships.filter(m=>m.userId===u.id&&m.rights.view);return row(['<strong>'+E(u.name)+'</strong><small>'+E(u.phone)+'</small>',E(App.time(u.registeredAt)),owned.length+' 台',added.length+' 台',owned.map(c=>'<div>'+E(Dev(c.deviceId)?.name)+'<small>'+E(App.time(c.end))+'</small></div>').join('')||'<span class="muted">暂无签约设备</span>',link('user-detail','客户详情',u.id)])});
 return head('CUSTOMER MASTER DATA','客户档案','手机号对应客户身份；资料、设备归属、租期与授权以本地主数据为准。',button('new-user','登记客户','user-round-plus','','primary'))+'<div class="banner">此 Demo 使用浏览器保存样例主档。正式系统将由本地电脑主数据库管理，云端与小程序跟随同步。</div><section class="panel"><div class="toolbar"><span class="muted">客户 '+S().users.filter(u=>u.role!=='admin').length+' 人</span><input id="admin-search" aria-label="搜索客户" value="'+E(q())+'" placeholder="姓名 / 微信绑定手机号"></div><div id="admin-results">'+table(['姓名 / 手机号','登记时间','名下设备','可查看设备','租期信息','操作'],rows)+'</div></section>';}
function openUser(){App.modal('登记客户','<form id="user-form"><div class="banner">按客户微信绑定的手机号登记。Demo 中模拟手机号绑定核验，不调用微信接口。</div>'+field('姓名',input('name','','text','required maxlength="40" placeholder="客户真实姓名"'))+field('微信绑定手机号',input('phone','','tel','required pattern="1[3-9][0-9]{9}" maxlength="11" placeholder="11 位手机号"'))+formEnd('登记客户'),el=>{const f=el.querySelector('form');f.onsubmit=ev=>{ev.preventDefault();try{D.registerUser(Object.fromEntries(new FormData(f)));App.closeModal();App.toast('客户已登记，可继续签约')}catch(err){App.error(f,err)}}})}
function userDetail(id){const u=U(id);if(!u)return;const members=S().memberships.filter(m=>m.userId===id);App.modal('客户档案 · '+u.name,'<dl class="info-list"><dt>手机号</dt><dd>'+E(u.phone)+'</dd><dt>登记时间</dt><dd>'+E(App.time(u.registeredAt))+'</dd><dt>主数据归属</dt><dd>本地主档 · v'+S().sync.localVersion+'</dd></dl>'+table(['关联设备','关系','操作权限'],members.map(m=>{const d=Dev(m.deviceId),c=D.contract(m.deviceId);return row([E(d?.name),c?.ownerId===id?App.badge('第一所有人','info'):App.badge('扫码关联','muted'),rightsMarkup(m.rights)])})),el=>{});}
function rightsMarkup(r){return [['view','查看'],['control','启停'],['frequency','调频'],['reset','复位']].filter(([k])=>r[k]).map(([,l])=>App.badge(l,'info')).join(' ')||App.badge('已撤销','muted')}
function permissions(){const chosen=App.ui.permissionDevice||'all',members=S().memberships.filter(m=>chosen==='all'||m.deviceId===chosen);return head('ACCESS CONTROL','用户授权','设备可由多人添加，启停、调频、故障复位分别授权。')+'<div class="banner">扫码仅建立查看权限。第一所有人按合同登记确定，也需管理员单独授予操作权限；撤销查看时同时撤销其余权限。</div><section class="panel"><div class="toolbar"><label class="row"><span class="muted">目标设备</span><select id="permission-device"><option value="all">全部设备</option>'+S().devices.map(d=>'<option value="'+E(d.id)+'" '+(chosen===d.id?'selected':'')+'>'+E(d.name)+'</option>').join('')+'</select></label>'+button('mini-scan','前往小程序扫码添加','scan-line','','small')+'</div>'+table(['设备','用户 / 手机号','关联关系','当前权限','操作'],members.map(m=>{const u=U(m.userId),d=Dev(m.deviceId),c=D.contract(m.deviceId);return row(['<strong>'+E(d?.name)+'</strong><small>'+E(m.deviceId)+'</small>',E(u?.name)+'<small>'+E(u?.phone)+'</small>',c?.ownerId===u?.id?App.badge('第一所有人','info'):App.badge('扫码关联','muted'),rightsMarkup(m.rights),'<button type="button" class="btn small" data-admin="grant" data-id="'+E(m.deviceId)+'" data-user="'+E(m.userId)+'">'+I('shield-check',15)+'设置权限</button>'])}))+'<div class="table-foot">未扫码关联的用户不会出现在授权名单中。合同登记后，签约客户也需先扫码建立查看关联。</div></section>'}
function openGrant(deviceId,userId){const m=D.membership(deviceId,userId),d=Dev(deviceId),u=U(userId);if(!m)return;App.modal('设置设备权限','<form id="grant-form"><dl class="info-list"><dt>目标设备</dt><dd>'+E(d.name)+'</dd><dt>授权用户</dt><dd>'+E(u.name)+' · '+E(u.phone)+'</dd><dt>设备关系</dt><dd>'+(D.contract(deviceId)?.ownerId===userId?'合同第一所有人':'扫码关联用户')+'</dd></dl><div class="stack" style="gap:13px;margin:22px 0">'+[['view','查看设备','查看运行指标、租期与历史'],['control','启停控制','远程启动与停止变频器'],['frequency','调整频率','在设备允许范围内设置目标频率'],['reset','故障复位','现场排查后提交复位指令']].map(([key,label,help])=>'<label class="check-row"><input type="checkbox" name="'+key+'" '+(m.rights[key]?'checked':'')+'><span><strong>'+label+'</strong><small class="muted" style="display:block">'+help+'</small></span></label>').join('')+'</div><div class="banner">操作权限仍受租期、在线状态与故障联锁约束。授权不会直接启动设备。</div>'+formEnd('保存授权'),el=>{const f=el.querySelector('form');f.elements.view.onchange=()=>{if(!f.elements.view.checked)['control','frequency','reset'].forEach(k=>f.elements[k].checked=false)};['control','frequency','reset'].forEach(k=>f.elements[k].onchange=()=>{if(f.elements[k].checked)f.elements.view.checked=true});f.onsubmit=ev=>{ev.preventDefault();try{D.grant(deviceId,userId,Object.fromEntries(['view','control','frequency','reset'].map(k=>[k,f.elements[k].checked])),'admin');App.closeModal();App.toast('权限已保存，小程序同步生效')}catch(err){App.error(f,err)}}})}


function reportCustomers(){const ids=new Set([...S().users.filter(u=>u.role!=='admin').map(u=>u.id),...S().receipts.map(r=>r.userId)]);return [...ids].map(id=>({id,name:U(id)?.name||S().receipts.find(r=>r.userId===id)?.userName||'历史客户',phone:U(id)?.phone||S().receipts.find(r=>r.userId===id)?.userPhone||'—'}));}
function reportData(){
 const tab=App.ui.reportTab||'device',receipts=monthlyReceipts();
 if(tab==='month'){
 const keys=[...new Set([month(S().now),...S().receipts.map(r=>month(r.paidAt))])].sort().reverse();
 return{headers:['收款月份','首次出租实收（元）','续租实收（元）','实收合计（元）','收款笔数','涉及设备'],rows:keys.map(k=>{const a=S().receipts.filter(r=>month(r.paidAt)===k);return[k,App.money(sum(a.filter(r=>r.type==='initial'))),App.money(sum(a.filter(r=>r.type==='renewal'))),App.money(sum(a)),a.length,new Set(a.map(r=>r.deviceId)).size]}),ids:keys.map(k=>'month:'+k)};
 }
 if(tab==='customer'){const users=reportCustomers();return{headers:['客户姓名','手机号','签约设备数','可查看设备数','本月实收（元）','累计实收（元）'],rows:users.map(u=>[u.name,u.phone,S().contracts.filter(c=>c.ownerId===u.id).length,S().memberships.filter(m=>m.userId===u.id&&m.rights.view).length,App.money(sum(receipts.filter(r=>r.userId===u.id))),App.money(sum(S().receipts.filter(r=>r.userId===u.id)))]),ids:users.map(u=>'customer:'+u.id)}}
 return{headers:['设备名称','设备 ID','4G 模块 ID','第一所有人','手机号','租约到期','租约状态','本月实收（元）'],rows:S().devices.map(d=>{const c=D.contract(d.id),u=U(c?.ownerId);return[d.name,d.id,d.module,u?.name||'待签约',u?.phone||'—',c?App.time(c.end):'—',D.lease(d.id).label,App.money(sum(receipts.filter(r=>r.deviceId===d.id)))]}),ids:S().devices.map(d=>'device:'+d.id)};
}
function reports(){
 const receipts=monthlyReceipts(),data=reportData(),total=sum(receipts);
 return head('FINANCIAL & DEVICE REPORTS','统计报表','专门的表格工作台，按设备、月份与客户追踪实际收款。',button('export-report','导出当前表格 CSV','download','','primary'))+
 '<div class="metric-grid">'+stat('本月实际收款',yen(total),selectedMonth()+' · 以收款日期为准','wallet')+stat('首次出租实收',yen(sum(receipts.filter(r=>r.type==='initial'))),'不包括未收款合同金额','file-plus-2')+stat('续租实际收款',yen(sum(receipts.filter(r=>r.type==='renewal'))),'续租成功登记的收款','repeat-2')+stat('本月收款笔数',receipts.length+'<small>笔</small>',new Set(receipts.map(r=>r.userId)).size+' 位付款客户','receipt-text')+'</div>'+
 '<section class="panel"><div class="toolbar"><div class="tabs">'+[['device','设备台账'],['month','月收入统计'],['customer','客户统计']].map(([key,label])=>'<button type="button" data-admin="report-tab" data-id="'+key+'" class="'+((App.ui.reportTab||'device')===key?'active':'')+'">'+label+'</button>').join('')+'</div><label class="row"><span class="muted" style="font-size:12px">统计月份</span><input type="month" id="report-month" value="'+E(selectedMonth())+'" style="width:160px" aria-label="统计月份"></label></div>'+table([...data.headers,'收款明细'],data.rows.map((r,i)=>row([...r.map(E),link('report-detail','查看明细',data.ids[i])])))+'<div class="table-foot">金额单位：人民币元。月收入表展示全部有记录月份；设备与客户表的“本月”按所选月份统计。</div></section>'+
 '<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>'+E(selectedMonth())+' · 单笔收款流水</h2>'+button('export-receipts','导出流水','download','','small')+'</div>'+receiptTable(receipts)+'</section>';
}
function receiptTable(receipts){return table(['收款时间','客户 / 设备','合同 / 类型','实收金额','凭证流水号','操作'],receipts.slice().sort((a,b)=>Date.parse(b.paidAt)-Date.parse(a.paidAt)).map(r=>row([E(App.time(r.paidAt)),E(customer(r.userId,r.userName))+'<small>'+E(Dev(r.deviceId)?.name||r.deviceId)+'</small>',E(r.contractNumber||S().contracts.find(c=>c.id===r.contractId)?.number||r.contractId)+'<small>'+(r.type==='renewal'?'续租':'首次出租')+'</small>','<strong>'+yen(r.amountCents)+'</strong>',E(r.reference),link('receipt','单笔详情',r.id)])));}
function receiptExport(receipts,name){csv(name,['流水 ID','收款时间','客户','手机号','设备 ID','设备名称','合同号','类型','实收金额（元）','收款凭证'],receipts.map(r=>[r.id,App.time(r.paidAt),customer(r.userId,r.userName),U(r.userId)?.phone||r.userPhone,r.deviceId,Dev(r.deviceId)?.name,r.contractNumber||S().contracts.find(c=>c.id===r.contractId)?.number||r.contractId,r.type==='renewal'?'续租':'首次出租',App.money(r.amountCents),r.reference]));}
function reportDetail(key){const [type,...parts]=key.split(':'),id=parts.join(':'),receipts=S().receipts.filter(r=>type==='month'?month(r.paidAt)===id:month(r.paidAt)===selectedMonth()&&(type==='device'?r.deviceId===id:r.userId===id));const title=type==='month'?id+' 月收入明细':type==='device'?(Dev(id)?.name||id)+' · '+selectedMonth():(customer(id))+' · '+selectedMonth();App.modal(title,'<div class="banner">共 '+receipts.length+' 笔，实际收款合计 '+yen(sum(receipts))+'。</div>'+receiptTable(receipts)+'<div class="form-actions"><button type="button" class="btn primary" id="export-drill">'+I('download',16)+'导出当前明细</button></div>',el=>{el.closest('.modal-card').classList.add('wide');el.onclick=onClick;el.querySelector('#export-drill').onclick=()=>receiptExport(receipts,'收款明细_'+Date.now()+'.csv')})}
function receiptDetail(id){const r=S().receipts.find(r=>r.id===id);if(!r)return;App.modal('单笔收款详情','<dl class="info-list"><dt>流水 ID</dt><dd>'+E(r.id)+'</dd><dt>收款时间</dt><dd>'+E(App.time(r.paidAt))+'</dd><dt>付款客户</dt><dd>'+E(customer(r.userId,r.userName))+' · '+E(U(r.userId)?.phone||r.userPhone)+'</dd><dt>设备</dt><dd>'+E(Dev(r.deviceId)?.name||r.deviceId)+'</dd><dt>合同号</dt><dd>'+E(r.contractNumber||S().contracts.find(c=>c.id===r.contractId)?.number||r.contractId)+'</dd><dt>收款类型</dt><dd>'+(r.type==='renewal'?'续租实收':'首次出租实收')+'</dd><dt>实际金额</dt><dd><strong style="font-size:23px;color:var(--brand)">'+yen(r.amountCents)+'</strong></dd><dt>凭证号</dt><dd>'+E(r.reference)+'</dd></dl><div class="banner">此流水为演示登记。恢复用户备份不会删除或回滚收款记录。</div><div class="form-actions">'+button('receipt-export','导出此笔流水','download',id,'primary')+'</div>',el=>el.onclick=onClick)}
function reminders(){
 const due=S().devices.filter(d=>['near','expired'].includes(D.lease(d.id).key)),messages=S().messages.slice().sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));
 return head('LEASE NOTIFICATIONS','到期与提醒','租期提前 7 天、3 天、1 天提醒；到期未续租进入停机流程。',button('scenarios','推进演示时钟','clock-3','','small'))+
 '<div class="metric-grid">'+stat('7 天内到期',due.filter(d=>D.lease(d.id).key==='near').length+'<small>台</small>','以合同结束时间为准','calendar-clock')+stat('已到期设备',due.filter(d=>D.lease(d.id).key==='expired').length+'<small>台</small>','停止请求与执行回执分别展示','power')+stat('站内消息',messages.length+'<small>条</small>',messages.filter(m=>!m.read).length+' 条客户未读','bell-ring')+stat('短信服务','预留接口','充值、计费与发送均未启用','message-square')+'</div>'+
 '<section class="panel"><div class="panel-head"><h2>租期处理清单</h2>'+App.badge('续租不自动启动','info')+'</div>'+table(['设备 / 第一所有人','到期时间','租约状态','最近停机回执','操作'],due.map(d=>{const c=D.contract(d.id),cmd=S().commands.find(x=>x.deviceId===d.id&&x.action==='stop');return row(['<strong>'+E(d.name)+'</strong><small>'+E(customer(c.ownerId))+'</small>',E(App.time(c.end)),badgeLease(d),cmd?E(commandStatus(cmd.status))+'<small>'+E(cmd.result)+'</small>':'<span class="muted">暂无停机指令</span>',button('renew','办理续租','',d.id,'small')])}))+'</section>'+
 '<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>客户站内消息</h2><span class="muted" style="font-size:11px">客户在小程序阅读后更新状态</span></div>'+table(['通知时间','接收客户','标题 / 内容','关联设备','阅读状态'],messages.map(m=>row([E(App.time(m.createdAt)),E(customer(m.userId)),'<strong>'+E(m.title)+'</strong><small style="max-width:380px;white-space:normal">'+E(m.body)+'</small>',E(Dev(m.deviceId)?.name||'—'),App.badge(m.read?'已读':'未读',m.read?'muted':'info')])))+'</section>';
}
function commandStatus(s){return({pending:'等待回执',succeeded:'执行成功',failed:'执行失败',uncertain:'结果待确认'})[s]||s}


function backup(){
 const s=S();return head('LOCAL MASTER & BACKUP','用户数据与本地备份','仅用户主数据以本地为准；运行数据、告警、指令与收款留在云端业务域。',button('backup-import','导入并预览','folder-open')+button('backup-export','生成加密备份','download','','primary'))+
 '<div class="banner warning">当前 Demo 的本地主档存储在本浏览器中，可实际生成与恢复加密备份文件。正式系统需部署本地数据库和同步服务，浏览器缓存不能替代本地数据库。</div>'+
 '<div class="metric-grid">'+stat('本地主档版本','v'+s.sync.localVersion,'用户资料、租约归属与授权','database')+stat('云端副本版本','v'+s.sync.cloudVersion,s.sync.online?'同步链路在线':'模拟主服务离线','cloud')+stat('待同步变更',s.sync.pending+'<small>版</small>','以本地确认版本覆盖云端副本','refresh-cw')+stat('已生成备份',s.backups.length+'<small>份</small>','请核对实际文件已妥善保存','hard-drive-download')+'</div>'+
 '<div class="split"><section class="panel"><div class="panel-head"><h2>用户主数据范围</h2>'+App.badge('本地权威','info')+'</div><div class="panel-body"><dl class="info-list"><dt>客户资料</dt><dd>姓名、微信绑定手机号、登记时间</dd><dt>设备归属</dt><dd>用户关联设备、第一所有人、合同编号</dd><dt>租赁与授权</dt><dd>租期起止、月租金、查看 / 启停 / 调频 / 复位权限</dd><dt>设备身份索引</dt><dd>设备 ID 与模块身份，用于恢复时核验关联</dd><dt>不纳入备份</dt><dd>电机采样、历史曲线、告警、控制指令、收款流水</dd></dl><div class="row" style="margin-top:20px">'+button('sync','立即同步','refresh-cw','','small')+button('scenarios','模拟同步断线','unplug','','small')+'</div></div></section><section class="panel"><div class="panel-head"><h2>U 盘 / 光盘保存</h2></div><div class="panel-body">'+[['01','生成加密文件','输入备份密码并下载 JSON 加密包。'],['02','另存 U 盘或刻录光盘','浏览器保存至本地或 U 盘；光盘由电脑刻录工具写入。'],['03','校验后恢复','使用“导入并预览”解密校验，核对后再确认恢复。']].map(([n,t,d])=>'<div class="guide-step"><span class="step-no">'+n+'</span><div><strong>'+t+'</strong><p>'+d+'</p></div></div>').join('')+'<p class="muted" style="font-size:11px;margin:14px 0 0">生成文件不等于完成外部介质保存。恢复后仍以当前时间判断到期，不回滚收款和设备状态。</p></div></section></div>'+
 '<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>备份生成记录</h2></div>'+table(['生成时间','源主档版本','用户数','合同数','文件格式','状态'],s.backups.map(b=>row([E(App.time(b.createdAt)),'v'+b.sourceVersion,b.users,b.contracts,E(b.format),E(b.status)])))+'</section>';
}
function exportBackup(){App.modal('生成用户主数据加密备份','<form id="backup-export-form"><div class="banner">备份包含用户、合同归属、租期与权限，不包含运行记录和收款流水。加密文件可保存至本地或 U 盘，再由电脑刻录到光盘。</div>'+field('设置备份密码',input('password','','password','required minlength="8" maxlength="200" autocomplete="new-password"'),'至少 8 个字符，请妥善保管；恢复时需要相同密码。')+field('再次输入密码',input('confirm','','password','required minlength="8" maxlength="200" autocomplete="new-password"'))+formEnd('生成并下载加密文件'),el=>{const f=el.querySelector('form');f.onsubmit=async ev=>{ev.preventDefault();const b=f.querySelector('button[type=submit]');try{if(f.elements.password.value!==f.elements.confirm.value)throw Error('两次输入的密码不一致');b.disabled=true;b.textContent='正在加密…';const data=await D.exportBackup(f.elements.password.value);App.download('用户主数据备份_v'+S().sync.localVersion+'_'+dateValue(S().now).replace(/[:T]/g,'-')+'.json',JSON.stringify(data,null,2));App.closeModal();App.toast('加密备份已生成，请确认下载文件保存完成')}catch(err){App.error(f,err)}finally{if(b.isConnected){b.disabled=false;b.textContent='生成并下载加密文件'}}}})}
function importBackup(){App.modal('导入用户备份 · 解密校验','<form id="backup-import-form"><div class="banner">先读取文件、核验密码与完整性，再展示恢复范围。此步骤不会修改任何数据。</div>'+field('选择备份文件','<input type="file" name="file" accept=".json,application/json" required>')+field('备份密码',input('password','','password','required minlength="8" maxlength="200" autocomplete="off"'))+formEnd('解密并预览'),el=>{const f=el.querySelector('form');f.onsubmit=async ev=>{ev.preventDefault();const b=f.querySelector('button[type=submit]');try{const file=f.elements.file.files[0];if(!file)throw Error('请选择备份文件');if(file.size>6000000)throw Error('备份文件过大，请使用此 Demo 导出的文件');b.disabled=true;b.textContent='正在校验…';const object=JSON.parse(await file.text()),inspected=await D.inspectBackup(object,f.elements.password.value);previewBackup(inspected,file.name)}catch(err){App.error(f,err instanceof SyntaxError?new Error('文件不是有效的 JSON 备份'):err)}finally{if(b.isConnected){b.disabled=false;b.textContent='解密并预览'}}}})}
function backupDifferences(payload){
 const current=S(),changes=[];
 const userName=(id,source)=>{const u=source.users.find(x=>x.id===id);return u?u.name+' · '+u.phone+' ('+id+')':id||'—'};
 const deviceName=id=>{const d=Dev(id);return d?d.name+' ('+id+')':id||'—'};
 const stamp=value=>value?App.time(value):'—';
 const compare=(domain,before,after,key,fields,label)=>{
  const oldMap=new Map(before.map(x=>[key(x),x])),newMap=new Map(after.map(x=>[key(x),x]));
  for(const id of new Set([...oldMap.keys(),...newMap.keys()])){
   const a=oldMap.get(id),b=newMap.get(id),object=label(a||b,a?current:payload);
   const value=(record,field,source)=>field[2]?field[2](record[field[0]],source):String(record[field[0]]??'—');
   const describe=(record,source)=>fields.map(field=>field[1]+'：'+value(record,field,source)).join('\n');
   if(!a||!b){changes.push({domain,object,field:!a?'新增记录':'删除记录',before:a?describe(a,current):'不存在',after:b?describe(b,payload):'不存在（恢复后移除）'});continue}
   for(const field of fields)if(a[field[0]]!==b[field[0]])changes.push({domain,object,field:field[1],before:value(a,field,current),after:value(b,field,payload)});
  }
 };
 compare('用户资料',current.users,payload.users,x=>x.id,[['name','姓名'],['phone','手机号'],['registeredAt','登记时间',stamp]],(u,source)=>userName(u.id,source));
 compare('合同归属与租期',current.contracts,payload.contracts,x=>x.id,[['number','合同编号'],['ownerId','第一所有人',userName],['start','租期开始',stamp],['end','租期结束',stamp]],c=>deviceName(c.deviceId)+' · '+c.number);
 const members=rows=>rows.map(m=>({deviceId:m.deviceId,userId:m.userId,...m.rights}));
 const rights=[['view','查看权限'],['control','启停权限'],['frequency','调频权限'],['reset','复位权限']].map(([key,label])=>[key,label,v=>v?'启用':'禁用']);
 compare('设备关联与授权',members(current.memberships),members(payload.memberships),m=>m.deviceId+':'+m.userId,rights,(m,source)=>deviceName(m.deviceId)+' · '+userName(m.userId,source));
 if(!changes.length)return '<section id="backup-differences"><h3>逐项差异（当前 → 备份）</h3><div class="banner">用户资料、合同归属、租期及四项权限与当前主档一致，没有字段差异。</div></section>';
 const wrap=value=>'<span style="display:block;white-space:pre-wrap;overflow-wrap:anywhere;max-width:260px">'+E(value)+'</span>';
 return '<section id="backup-differences" style="margin:22px 0"><h3>逐项差异（当前 → 备份）</h3><p class="muted" style="font-size:12px">共 '+changes.length+' 项变化；“删除记录”表示恢复后该条用户主档记录将移除。以下不含运行数据和收款流水。</p>'+table(['具体对象','变更项目','当前值','备份值（恢复后）'],changes.map(change=>'<tr data-diff-domain="'+E(change.domain)+'" data-diff-field="'+E(change.field)+'">'+cell('<strong>'+E(change.domain)+'</strong>'+wrap(change.object))+cell(E(change.field))+cell(wrap(change.before))+cell(wrap(change.after))+'</tr>'))+'</section>';
}
function previewBackup(inspected,filename){
 const p=inspected.payload,c=inspected.conflicts||[],summary=inspected.summary,previewVersion=S().sync.localVersion;
 App.modal('恢复预览 · '+filename,'<form id="backup-restore-form"><div class="banner '+(c.length?'danger':'')+'">'+(c.length?'发现关联冲突，请处理后重新导入。':'密码、文件完整性与数据结构校验通过。')+'</div><dl class="info-list"><dt>备份生成时间</dt><dd>'+E(App.time(p.createdAt))+'</dd><dt>备份主档版本</dt><dd>v'+E(p.sourceVersion)+'</dd><dt>用户资料</dt><dd>当前 '+S().users.length+' → 备份 '+summary.users+' 人</dd><dt>合同与租期</dt><dd>当前 '+S().contracts.length+' → 备份 '+summary.contracts+' 份</dd><dt>关联与授权</dt><dd>当前 '+S().memberships.length+' → 备份 '+summary.memberships+' 条</dd></dl>'+(c.length?'<ul>'+c.map(x=>'<li>'+E(x)+'</li>').join('')+'</ul>':'')+backupDifferences(p)+'<div class="banner warning">确认恢复将以备份中的用户资料、合同归属、租期与权限替换当前用户主档。电机运行数据、告警、指令和收款流水不会回滚；已到期合同仍按当前时间锁定。</div><div class="row" style="margin:16px 0">'+button('save-current-before-restore','先导出当前备份','download','','small')+'<span class="muted" style="font-size:11px">导出后需重新导入待恢复文件，重新核对差异。</span></div><label class="check-row"><input type="checkbox" name="confirmed" required><span>我已逐项核对新增、删除及字段变化，确认用备份值替换当前用户主档；运行记录和收款流水保持不变。</span></label><div class="form-actions"><button type="button" class="btn" data-close>取消</button><button type="submit" class="btn danger" '+(c.length?'disabled':'')+'>确认恢复用户主档</button></div></form>',el=>{
 el.closest('.modal-card').classList.add('wide');const f=el.querySelector('form');
 el.querySelector('[data-admin="save-current-before-restore"]').onclick=()=>exportBackup();
 f.onsubmit=ev=>{ev.preventDefault();try{if(!f.elements.confirmed.checked)throw Error('请先逐项核对并确认恢复范围');if(S().sync.localVersion!==previewVersion)throw Error('当前用户主档在预览后发生变更，请重新导入并核对最新差异');D.restoreBackup(inspected);App.closeModal();App.toast('用户主档已恢复；运行记录和收款流水保持不变')}catch(err){App.error(f,err)}};
 });
}
function logs(){const tab=App.ui.logTab||'operations';return head('AUDIT & COMMAND HISTORY','操作记录','关键业务变更可追溯，指令提交和设备执行回执分开记录。')+'<section class="panel"><div class="toolbar"><div class="tabs">'+[['operations','业务操作日志'],['commands','设备指令回执']].map(([k,l])=>'<button type="button" data-admin="log-tab" data-id="'+k+'" class="'+(tab===k?'active':'')+'">'+l+'</button>').join('')+'</div><span class="muted" style="font-size:11px">记录均来自当前演示状态</span></div>'+(tab==='commands'?table(['提交时间','设备 / 操作者','操作','状态','执行结果'],S().commands.map(c=>row([E(App.time(c.createdAt)),E(Dev(c.deviceId)?.name||c.deviceId)+'<small>'+E(c.userId==='system'?'租期策略':customer(c.userId))+'</small>',E(({start:'启动',stop:'停止',frequency:'调频',reset:'故障复位'})[c.action])+(c.action==='frequency'?' '+E(c.value)+' Hz':''),App.badge(commandStatus(c.status),c.status==='succeeded'?'success':c.status==='failed'?'danger':'warning'),'<span style="white-space:normal">'+E(c.result)+'</span>']))):table(['操作时间','操作人','业务动作','关联设备','操作说明'],S().logs.map(l=>row([E(App.time(l.time)),E(l.actor==='system'?'系统':customer(l.actor,l.actor)),E(l.action),E(Dev(l.deviceId)?.name||'—'),'<span style="white-space:normal;display:block;max-width:520px">'+E(l.detail)+'</span>']))))+'</section>'}
function settings(){return head('SERVICES & INTERFACES','服务与接口','演示功能范围和后续真实系统的连接位置。')+'<div class="split"><section class="panel"><div class="panel-head"><h2>短信充值服务</h2>'+App.badge('仅预留接口','warning')+'</div><div class="panel-body"><dl class="info-list"><dt>计费方式</dt><dd>用户预充值，按发送条数扣费（规划）</dd><dt>当前状态</dt><dd>未接入供应商、未启用充值与发送</dd><dt>短信单价</dt><dd>待确定</dd><dt>提醒节点</dt><dd>到期前 7 / 3 / 1 天</dd><dt>本期消息</dt><dd>使用小程序站内消息模拟展示</dd></dl><div class="row" style="margin-top:20px"><button type="button" class="btn" disabled>'+I('wallet',16)+'充值服务待开放</button><button type="button" class="btn" disabled>'+I('send',16)+'短信发送未启用</button></div></div></section><section class="panel"><div class="panel-head"><h2>演示环境</h2>'+App.badge('本地 Demo','info')+'</div><div class="panel-body"><dl class="info-list"><dt>设备连接</dt><dd>4G → 自有云，当前为模拟数据</dd><dt>微信身份</dt><dd>手机号绑定使用样例身份模拟</dd><dt>收入登记</dt><dd>实际收款台账模拟，不发起支付</dd><dt>文件备份</dt><dd>可生成、下载、解密与恢复用户主档</dd><dt>正式接入</dt><dd>本地数据库、云 API、4G 通信协议、微信扫码</dd></dl>'+button('guide','查看演示指南','circle-help','','small')+'</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>后续接入清单</h2></div>'+table(['服务','Demo 当前实现','正式系统接入'],[['微信小程序','手机视图、扫码样例、相机能力探测','手机号授权、真实扫码、订阅消息'],['4G 设备通信','指令状态机与回执模拟','模块鉴权、遥测上报、指令回执与终端到期策略'],['本地主数据','浏览器样例主档与加密备份','本地数据库、版本同步、离线保障与介质备份'],['云运行数据','趋势、告警和记录模拟','云时序存储、告警服务、租期服务'],['短信服务','入口及业务规则预留','供应商、单价、充值、计费、回执接口']].map(row))+'</section>'}


function go(page){App.closeModal();App.navigate('admin',page)}
function onClick(event){
 const b=event.target.closest('[data-admin]');if(!b||b.disabled)return;const action=b.dataset.admin,id=b.dataset.id;
 try{
  if(action.startsWith('goto-'))return go(action.slice(5));
  if(action==='inventory')return App.openInventory();
  if(action==='device')return deviceDetail(id);
  if(action==='monitor-device'){App.closeModal();return App.navigate('monitor','detail',id)}
  if(action==='contract')return openContract(id);
  if(action==='renew')return openRenew(id);
  if(action==='lease')return App.openLease(id);
  if(action==='new-user')return openUser();
  if(action==='user-detail')return userDetail(id);
  if(action==='grant')return openGrant(id,b.dataset.user);
  if(action==='permissions-device'){App.ui.permissionDevice=id;return go('permissions')}
  if(action==='device-filter'){App.ui.deviceFilter=id;return App.render()}
  if(action==='report-tab'){App.ui.reportTab=id;return App.render()}
  if(action==='log-tab'){App.ui.logTab=id;return App.render()}
  if(action==='mini-scan'){App.closeModal();return App.navigate('mini','devices')}
  if(action==='report-detail')return reportDetail(id);
  if(action==='receipt')return receiptDetail(id);
  if(action==='receipt-export')return receiptExport(S().receipts.filter(r=>r.id===id),'收款流水_'+id+'.csv');
  if(action==='export-receipts')return receiptExport(monthlyReceipts(),'收款流水_'+selectedMonth()+'.csv');
  if(action==='export-report'){const data=reportData();return csv('统计表_'+({device:'设备台账',month:'月收入',customer:'客户统计'})[App.ui.reportTab||'device']+'_'+selectedMonth()+'.csv',data.headers,data.rows)}
  if(action==='backup-export')return exportBackup();
  if(action==='backup-import')return importBackup();
  if(action==='sync'){D.syncNow();return App.toast('本地主档已同步至云端副本（模拟）')}
  if(action==='scenarios')return App.openScenarios();
  if(action==='guide')return App.openGuide();
 }catch(err){App.toast(err.message||'操作失败，请重试')}
}
const pages={overview,devices,leases,users,permissions,reports,reminders,backup,logs,settings};
function render(el){
 el.innerHTML=(pages[App.ui.page]||overview)()+'<footer class="demo-footer"><span>云控 · 统一设备租赁与监控工作台</span><span>DEMO · 示例数据 · 不连接真实设备</span></footer>';
 el.onclick=onClick;
 el.oninput=event=>{if(event.target.id==='admin-search'){App.ui.adminSearch=App.ui.adminSearch||{};App.ui.adminSearch[App.ui.page]=event.target.value;const dest=el.querySelector('#admin-results');if(dest){const virtual=document.createElement('div');virtual.innerHTML=pages[App.ui.page]();dest.innerHTML=virtual.querySelector('#admin-results').innerHTML;App.icons?.()}}};
 el.onchange=event=>{if(event.target.id==='permission-device'){App.ui.permissionDevice=event.target.value;App.render()}if(event.target.id==='report-month'&&/^\d{4}-\d{2}$/.test(event.target.value)){App.ui.reportMonth=event.target.value;App.render()}};
}
globalThis.Admin={render};
})();


